import pandas as pd

def morning_rows(log):
    """Return the rows logged from 08:00 up to, but not including, 12:00."""
    # Ensure the log index is timezone-aware
    if not log.index.tzinfo:
        log.index = log.index.tz_localize('UTC')

    return log.between_time("08:00", "12:00", include_end=False)
```

