import numpy as np


def as_complex(values):
    """Return the values as an array of double-precision complex numbers."""
    if isinstance(values, np.ndarray):
        return np.asarray(values, dtype=np.complex_)
    else:
        return np.array(values, dtype=np.complex_)
```

